class Solution {
public:
    vector<long long> countKConstraintSubstrings(string s, int k, vector<vector<int>>& queries) {
        int n = s.size();
        vector<int> f(n, n), g(n);
        int cnt[2] = {0, 0};
        for (int r = 0, l = 0; r < n; r++) {
            cnt[s[r] - '0']++;
            while (cnt[0] > k && cnt[1] > k) cnt[s[l++] - '0']--;
            f[r] = l;
        }
        for (int p = 0; p < n; p++) g[p] = min(p, f[p] - 1);
        vector<long long> pre(n + 1, 0);
        for (int p = 0; p < n; p++) pre[p + 1] = pre[p] + g[p];
        vector<long long> ans;
        for (auto& q : queries) {
            int lo = q[0], hi = q[1];
            long long len = hi - lo + 1;
            long long total = len * (len + 1) / 2;
            int t = lower_bound(g.begin() + lo, g.begin() + hi + 1, lo) - g.begin();
            long long bad = (pre[hi + 1] - pre[t]) - (long long)(hi - t + 1) * (lo - 1);
            ans.push_back(total - bad);
        }
        return ans;
    }
};

