class Solution {
    public long[] countKConstraintSubstrings(String s, int k, int[][] queries) {
        int n = s.length();
        int[] f = new int[n], g = new int[n];
        Arrays.fill(f, n);
        int[] cnt = new int[2];
        for (int r = 0, l = 0; r < n; r++) {
            cnt[s.charAt(r) - '0']++;
            while (cnt[0] > k && cnt[1] > k) cnt[s.charAt(l++) - '0']--;
            f[r] = l;
        }
        for (int p = 0; p < n; p++) g[p] = Math.min(p, f[p] - 1);
        long[] pre = new long[n + 1];
        for (int p = 0; p < n; p++) pre[p + 1] = pre[p] + g[p];
        long[] ans = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int lo = queries[qi][0], hi = queries[qi][1];
            long len = hi - lo + 1, total = len * (len + 1) / 2;
            int t = lo;
            int a = lo, b = hi + 1;
            while (a < b) { int m = (a + b) >>> 1; if (g[m] >= lo) b = m; else a = m + 1; }
            t = a;
            long bad = (pre[hi + 1] - pre[t]) - (long)(hi - t + 1) * (lo - 1);
            ans[qi] = total - bad;
        }
        return ans;
    }
}

