var countKConstraintSubstrings = function(s, k, queries) {
    const n = s.length;
    const f = new Array(n).fill(n), g = new Array(n);
    const cnt = [0, 0];
    for (let r = 0, l = 0; r < n; r++) {
        cnt[s[r]]++;
        while (cnt[0] > k && cnt[1] > k) cnt[s[l++]]--;
        f[r] = l;
    }
    for (let p = 0; p < n; p++) g[p] = Math.min(p, f[p] - 1);
    const pre = new Array(n + 1).fill(0);
    for (let p = 0; p < n; p++) pre[p + 1] = pre[p] + g[p];
    return queries.map(([lo, hi]) => {
        const len = hi - lo + 1;
        const total = len * (len + 1) / 2;
        let a = lo, b = hi + 1;
        while (a < b) { const m = (a + b) >> 1; if (g[m] >= lo) b = m; else a = m + 1; }
        const bad = (pre[hi + 1] - pre[a]) - (hi - a + 1) * (lo - 1);
        return total - bad;
    });
};
